import React, { useRef, useEffect, useState, useCallback } from 'react';
import Layout from '../components/layout';

const lightboxStyles = `
.lightbox-overlay {
  position: fixed;
  top: 0; left: 0; right: 0; bottom: 0;
  background: rgba(0,0,0,0.85);
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 9999;
  cursor: zoom-out;
  animation: fadeIn 0.2s ease;
}

.lightbox-overlay img {
  max-width: 90vw;
  max-height: 90vh;
  border-radius: 4px;
  box-shadow: 0 4px 32px rgba(0,0,0,0.5);
  animation: scaleIn 0.2s ease;
}

.lightbox-overlay .close-btn {
  position: absolute;
  top: 16px;
  right: 24px;
  color: #fff;
  font-size: 32px;
  cursor: pointer;
  opacity: 0.7;
  transition: opacity 0.15s;
  background: none;
  border: none;
  font-family: sans-serif;
}
.lightbox-overlay .close-btn:hover { opacity: 1; }

@keyframes fadeIn { from { opacity: 0; } to { opacity: 1; } }
@keyframes scaleIn { from { transform: scale(0.9); } to { transform: scale(1); } }

.svg-pan-zoom-container {
  border: 1px solid #e2e8f0;
  border-radius: 8px;
  margin: 12px 0;
  overflow: hidden;
  background: #fff;
  position: relative;
}

.svg-pan-zoom-container svg {
  display: block;
  width: 100%;
  height: auto;
}

.svg-pan-zoom-container .pan-hint {
  position: absolute;
  bottom: 12px;
  left: 50%;
  transform: translateX(-50%);
  background: rgba(0,0,0,0.65);
  color: #fff;
  font-size: 12px;
  padding: 4px 12px;
  border-radius: 4px;
  pointer-events: none;
  opacity: 0;
  transition: opacity 0.3s;
}

.svg-pan-zoom-container .pan-hint.visible {
  opacity: 1;
}
`;

export default function DocTemplate({ pageContext }) {
  const { html } = pageContext;
  const contentRef = useRef(null);
  const [lightboxSrc, setLightboxSrc] = useState(null);
  const svgInitRef = useRef(false);

  const handleKeyDown = useCallback((e) => {
    if (e.key === 'Escape') setLightboxSrc(null);
  }, []);

  useEffect(() => {
    const el = contentRef.current;
    if (!el) return;

    const imgs = el.querySelectorAll('img');
    const handlers = [];

    imgs.forEach((img) => {
      if (img.closest('.anchor-link') || img.closest('a')) return;
      if (img.alt === 'ORB Trading Pipeline') return;
      img.style.cursor = 'zoom-in';
      const handler = () => setLightboxSrc(img.src);
      img.addEventListener('click', handler);
      handlers.push([img, handler]);
    });

    document.addEventListener('keydown', handleKeyDown);

    return () => {
      handlers.forEach(([img, h]) => img.removeEventListener('click', h));
      document.removeEventListener('keydown', handleKeyDown);
    };
  }, [html, handleKeyDown]);

  useEffect(() => {
    if (svgInitRef.current) return;
    const el = contentRef.current;
    if (!el) return;

    const img = el.querySelector('img[alt="ORB Trading Pipeline"]');
    if (!img) return;

    svgInitRef.current = true;

    const container = document.createElement('div');
    container.className = 'svg-pan-zoom-container';
    const hint = document.createElement('div');
    hint.className = 'pan-hint';
    hint.textContent = 'Click and drag to pan · Scroll to zoom';
    container.appendChild(hint);

    img.parentNode.replaceChild(container, img);

    fetch(img.src.replace(/\.png$/, '.svg'))
      .then((r) => r.text())
      .then((svgContent) => {
        container.insertAdjacentHTML('afterbegin', svgContent);
        const svg = container.querySelector('svg');
        if (!svg) return;

        svg.removeAttribute('width');
        svg.removeAttribute('height');
        svg.style.maxWidth = 'none';
        svg.style.cursor = 'grab';

        const loadSvgPanZoom = () => {
          if (typeof svgPanZoom !== 'undefined') {
            const panZoom = svgPanZoom(svg, {
              zoomEnabled: true,
              controlIconsEnabled: false,
              fit: true,
              center: true,
              minZoom: 0.5,
              maxZoom: 10,
              customEventsHandler: {
                haltEventListeners: [],
                init: function (options) {
                  this.options = options;
                },
                destroy: function () {}
              }
            });

            svg.addEventListener('mousedown', () => { svg.style.cursor = 'grabbing'; });
            svg.addEventListener('mouseup', () => { svg.style.cursor = 'grab'; });

            hint.classList.add('visible');
            setTimeout(() => hint.classList.remove('visible'), 3000);

            return;
          }
          setTimeout(loadSvgPanZoom, 200);
        };

        const script = document.createElement('script');
        script.src = 'https://cdn.jsdelivr.net/npm/svg-pan-zoom@3.6.1/dist/svg-pan-zoom.min.js';
        script.onload = loadSvgPanZoom;
        document.body.appendChild(script);
      });
  }, [html]);

  return (
    <Layout>
      <style>{lightboxStyles}</style>
      <div ref={contentRef} className="md-content" dangerouslySetInnerHTML={{ __html: html }} />
      {lightboxSrc && (
        <div className="lightbox-overlay" onClick={() => setLightboxSrc(null)}>
          <button className="close-btn" onClick={() => setLightboxSrc(null)}>&times;</button>
          <img src={lightboxSrc} alt="enlarged view" onClick={(e) => e.stopPropagation()} />
        </div>
      )}
    </Layout>
  );
}
